    dx_free = [dx_free x_free(i)-x_free(i-1)];
    F_act_W_free = [F_act_W_free dW_free(end)/dx_free(end)-S_end*1/2*(P_free(i) + P_free(i-1))];
end

%%
W_act = zeros(15, 30);
F_ela = zeros(15, 29);
F_act = zeros(15, 29);
F_act_W = zeros(15, 29);
k_ela = zeros(15, 28);
x_ela = zeros(15, 28);
k_ela_all = [];
x_ela_all = [];

k_act_poly_result = [];
k_act_poly_error = [];
k_act_poly_errorratio = [];

minP = 5;
f1 = figure(1)
f1.Position = [500 500 300 200]; 
hold on
grid on
box on
for i = size(P_cons,1)-minP:-1:1
    P_max = P_cons(i,1)/1000;
    N_step1 = 1;
    N_step2 = P_max*2;
    
    for j = N_step1+1:N_step2
        dV = V_cons(i,j) - V_cons(i,j-1);
        dW = 1/2*(P_cons(i,j)+P_cons(i,j-1))*dV;
        dx = x_cons(i,j) - x_cons(i,j-1);
        W_act(i,j) = W_act(i,j-1) + dW;
        F_act_W(i,j-1) = dW/dx-S_end*1/2*(P_cons(i,j)+P_cons(i,j-1));
    end
    
    dU = U_cons(i, N_step1+1:N_step2) - U_cons(i, N_step1:N_step2-1);
    dx = x_cons(i, N_step1+1:N_step2) - x_cons(i, N_step1:N_step2-1); 
    
    
    x1 = 1/2*(x_cons(i, N_step1:N_step2-1) + x_cons(i, N_step1+1:N_step2)); % corresponding to force values
    x2 = 1/2*(x1(1:end-1) + x1(2:end)); % corresponding to stiffness values
    
    F_ela(i,N_step1:N_step2-1) = dU./dx; % no counting for the free-loading part
    F_act(i,N_step1:N_step2-1) = F_ela(i,N_step1:N_step2-1) + 1/2*(F_ext(i, N_step1:N_step2-1) + F_ext(i, N_step1+1:N_step2));

    dF_ela = F_ela(i, N_step1+1:N_step2-1) - F_ela(i, N_step1:N_step2-2);
    dF_act = F_act(i, N_step1+1:N_step2-1) - F_act(i, N_step1:N_step2-2);

    k_ela_all = [k_ela_all dF_ela./(x1(2:end) - x1(1:end-1))]; % accumlating with P
    x_ela_all = [x_ela_all x2]; % accumlating with P
    k_ela(i, N_step1:N_step2-2) = dF_ela./(x1(2:end) - x1(1:end-1));
    x_ela(i, N_step1:N_step2-2) = x2;
    
    k_act = dF_act./(x1(2:end) - x1(1:end-1)); % for each P

    k_act_poly = polyval(polyfit(x2, k_act, 0), x2); % for each P
    k_act_poly_result = [k_act_poly_result; polyfit(x2, k_act, 0)]; % accumlating with P
    
    k_act_poly_error = [k_act_poly_error sqrt(mean((k_act - k_act_poly).^2))];
    k_act_poly_errorratio = [k_act_poly_errorratio k_act_poly_error(end)/k_act_poly_result(end)*100];
    if (P_max == 5) || (P_max == 10) || (P_max == 15) 
        color = [0.9290 0.6940 0.1250; 0.8500 0.3250 0.0980; 0 0.4470 0.7410]; % rows for 15, 10, 5kPa

        plot(x2*1000, k_act, 'x', 'Color', color(1+floor(i/5),:), 'LineWidth', 1)
        plot(x2*1000, k_act_poly_result(end)*ones(1, length(x2)), '-', 'Color', color(1+floor(i/5),:), 'LineWidth', 1)
    end
end
